$assembly=[Reflection.Assembly]::LoadFrom((Join-Path $ProjectRoot 'bin\x64\Debug\HalconWinFormsDemo.exe'))
function Pump([int]$ms){$frame=New-Object Windows.Threading.DispatcherFrame;$timer=New-Object Windows.Threading.DispatcherTimer;$timer.Interval=[TimeSpan]::FromMilliseconds($ms);$timer.Add_Tick({$timer.Stop();$frame.Continue=$false});$timer.Start();[Windows.Threading.Dispatcher]::PushFrame($frame)}
function WaitTask($task){$watch=[Diagnostics.Stopwatch]::StartNew();while((-not $task.IsCompleted)-and($watch.ElapsedMilliseconds-lt 30000)){Pump 20};if(-not $task.IsCompleted){throw 'Task timeout'};if($task.IsFaulted){throw $task.Exception.Flatten().InnerExceptions[0]};$task.GetAwaiter().GetResult()|Out-Null}
function Shot([string]$path){$window.UpdateLayout();$a=$window.PointToScreen([Windows.Point]::new(0,0));$b=$window.PointToScreen([Windows.Point]::new($window.ActualWidth,$window.ActualHeight));$w=[Math]::Max(1,[int][Math]::Ceiling($b.X-$a.X));$h=[Math]::Max(1,[int][Math]::Ceiling($b.Y-$a.Y));$bitmap=[Drawing.Bitmap]::new($w,$h);$graphics=[Drawing.Graphics]::FromImage($bitmap);try{$graphics.CopyFromScreen([int]$a.X,[int]$a.Y,0,0,[Drawing.Size]::new($w,$h));$bitmap.Save($path,[Drawing.Imaging.ImageFormat]::Png)}finally{$graphics.Dispose();$bitmap.Dispose()};"${w}x${h}"}
function ImageFile([string]$path,[int]$seed){$bitmap=[Drawing.Bitmap]::new(720,480);$g=[Drawing.Graphics]::FromImage($bitmap);try{$g.Clear([Drawing.Color]::FromArgb(22,32,50));$brush=[Drawing.SolidBrush]::new([Drawing.Color]::FromArgb(225,60+($seed*19)%160,80+($seed*29)%150));try{$g.FillRectangle($brush,55+$seed*10,65,260,145);$g.FillEllipse($brush,390,120+$seed*5,180,180)}finally{$brush.Dispose()};$bitmap.Save($path,[Drawing.Imaging.ImageFormat]::Png)}finally{$g.Dispose();$bitmap.Dispose()}}
function SourceXld(){[double[]]$rows=@(90,90,205,205,90);[double[]]$cols=@(120,400,400,120,120);[HalconDotNet.HObject]$x=$null;[HalconDotNet.HOperatorSet]::GenContourPolygonXld([ref]$x,[HalconDotNet.HTuple]$rows,[HalconDotNet.HTuple]$cols);$x}
$temp=Join-Path([IO.Path]::GetTempPath())('halcon-vm-s41-ui-'+[Guid]::NewGuid().ToString('N'));[IO.Directory]::CreateDirectory($temp)|Out-Null;for($i=1;$i-le9;$i++){ImageFile (Join-Path $temp (('{0:00}_part.png'-f$i))) $i};[IO.File]::WriteAllBytes((Join-Path $temp '10_corrupt.png'),[byte[]](1,2,3))
foreach($path in @($QueueOutputPath,$AffineOutputPath)){$parent=[IO.Path]::GetDirectoryName($path);if(-not[string]::IsNullOrWhiteSpace($parent)){[IO.Directory]::CreateDirectory($parent)|Out-Null}}
$app=[Windows.Application]::Current;if($null-eq$app){$app=New-Object Windows.Application;$app.ShutdownMode=[Windows.ShutdownMode]::OnExplicitShutdown}
$main=$assembly.GetType('HalconWinFormsDemo.MainWindow',$true);$serviceType=$assembly.GetType('HalconWinFormsDemo.Services.RecipeService',$true);$loggerType=$assembly.GetType('HalconWinFormsDemo.Services.AppLogger',$true);$kindType=$assembly.GetType('HalconWinFormsDemo.Models.VmToolKind',$true);$snapshotType=$assembly.GetType('HalconWinFormsDemo.Models.VmXldSnapshot',$true);$private=[Reflection.BindingFlags]'Instance,NonPublic';$all=[Reflection.BindingFlags]'Instance,NonPublic,Public';$args=New-Object 'object[]' 1;$args[0]=$temp.ToString();$service=$serviceType.GetConstructor([Type[]]@([string])).Invoke($args);$logger=$loggerType.GetConstructor([Type[]]@([string])).Invoke($args);$window=$main.GetConstructor($private,$null,[Type[]]@($serviceType,$loggerType),$null).Invoke([object[]]@($service,$logger))
function F([string]$name){$main.GetField($name,$all).GetValue($window)}
$flow=$main.GetField('flowTools',$private).GetValue($window);$dispose=$main.GetMethod('DisposeFlowTools',$private);$create=$main.GetMethod('CreateFlowTool',$private);function Tool([string]$kind,[string]$name){$create.Invoke($window,[object[]]@([Enum]::Parse($kindType,$kind),$name,$true,$null))}
$window.WindowStartupLocation=[Windows.WindowStartupLocation]::Manual;$window.Left=2;$window.Top=2;$window.Width=1900;$window.Height=1060;$window.Topmost=$true;$window.Show();$window.Activate()|Out-Null;Pump 500
$dispose.Invoke($window,@())|Out-Null;$flow.Clear();$threshold=Tool ImageThreshold 'Queue Full Domain';$threshold.Parameters.ImageThresholdMinGray=0;$threshold.Parameters.ImageThresholdMaxGray=255;$flow.Add($threshold)
$paths=Get-ChildItem -LiteralPath $temp -File|Sort-Object Name|ForEach-Object FullName;$loadQueue=$main.GetMethods($private)|Where-Object{$_.Name-eq'LoadImageQueue'-and$_.GetParameters().Count-eq1}|Select-Object -First 1;$arg=New-Object 'object[]' 1;$arg[0]=[string[]]$paths;$loadQueue.Invoke($window,$arg)|Out-Null;(F 'ImageQueueRunScopeComboBox').SelectedIndex=2;(F 'ContinuousIntervalTextBox').Text='50';(F 'FlowTimeoutTextBox').Text='0';(F 'StopOnNgCheckBox').IsChecked=$false
WaitTask ($main.GetMethod('RunImageQueueBatchAsync',$private).Invoke($window,@()));Pump 700;$queueSize=Shot $QueueOutputPath

$dispose.Invoke($window,@())|Out-Null;$flow.Clear();$producer=Tool SubpixelEdgeExtraction 'Product Edge XLD';$affine=Tool XldAffineTransform 'Position Compensation';$fit=Tool XldLineFitting 'Transformed Line Fit';$affine.SetInputBinding('XLD',$producer.ToolId,'XLD');$fit.SetInputBinding('XLD',$affine.ToolId,'XLD');$affine.Parameters.XldAffineTranslateRow=34;$affine.Parameters.XldAffineTranslateColumn=48;$affine.Parameters.XldAffineScaleRow=1.12;$affine.Parameters.XldAffineScaleColumn=.92;$affine.Parameters.XldAffineRotationDegrees=12;$affine.Parameters.XldAffineSlantDegrees=5;$affine.Parameters.XldAffineTransformOrder='ScaleSlantRotateTranslate';foreach($tool in @($producer,$affine,$fit)){$flow.Add($tool)}
$xld=SourceXld;try{$snapshot=$snapshotType.GetMethod('Create',[Reflection.BindingFlags]'Static,Public').Invoke($null,[object[]]@($xld,$producer.ToolId,$producer.InstanceName,'XLD'));$producer.SetOutputValue('XLD',$snapshot);$producer.SetOutputValue('ContourCount',[double]1);$producer.ResultCode='OK'}finally{$xld.Dispose()}
$execute=$main.GetMethod('ExecuteFlowTool',$private);foreach($tool in @($affine,$fit)){$execute.Invoke($window,[object[]]@($tool,'S41 UI capture'))|Out-Null};(F 'FlowToolList').SelectedItem=$affine;$main.GetMethod('LoadDockConfigurationDraft',$private).Invoke($window,[object[]]@($affine))|Out-Null;(F 'RightTabs').SelectedItem=(F 'DockConfigurationTab');(F 'DockConfigurationTabs').SelectedIndex=0;(F 'ImageQueuePanel').Visibility=[Windows.Visibility]::Collapsed;(F 'ImageQueuePanelToggleButton').IsChecked=$false;(F 'ImageWorkspaceRow').Height=[Windows.GridLength]::new(300);(F 'RightConfigurationRow').Height=[Windows.GridLength]::new(430);$main.GetMethod('RefreshResultOverlayLayers',$private).Invoke($window,@())|Out-Null;$main.GetMethod('RefreshFlowSelectionFlags',$private).Invoke($window,@())|Out-Null;$main.GetMethod('ScheduleRefreshDisplay',$private).Invoke($window,@())|Out-Null;Pump 300;(F 'DockBasicParametersScrollViewer').ScrollToVerticalOffset(105);Pump 800;$affineSize=Shot $AffineOutputPath
$main.GetField('recipeCloseConfirmed',$private).SetValue($window,$true);$window.Close();$app.Shutdown();if(Test-Path $temp){Remove-Item -LiteralPath $temp -Recurse -Force}
